```javascript
class SimpleNeuralNetwork {
  constructor(inputSize, hiddenSize, outputSize, learningRate = 0.1) {
    this.inputSize = inputSize;
    this.hiddenSize = hiddenSize;
    this.outputSize = outputSize;
    this.learningRate = learningRate;

    // Initialize weights with random values
    this.weightsInputHidden = this.createMatrix(this.hiddenSize, this.inputSize, () => Math.random() * 2 - 1);
    this.weightsHiddenOutput = this.createMatrix(this.outputSize, this.hiddenSize, () => Math.random() * 2 - 1);

    // Initialize biases with random values
    this.biasHidden = this.createMatrix(this.hiddenSize, 1, () => Math.random() * 2 - 1);
    this.biasOutput = this.createMatrix(this.outputSize, 1, () => Math.random() * 2 - 1);
  }

  // Utility: create a matrix (2D array)
  createMatrix(rows, cols, filler = () => 0) {
    let matrix = [];
    for (let i = 0; i < rows; i++) {
      let row = [];
      for (let j = 0; j < cols; j++) {
        row.push(filler());
      }
      matrix.push(row);
    }
    return matrix;
  }

  // Utility: matrix multiplication
  static multiply(a, b) {
    if (a[0].length !== b.length) {
      throw new Error('Matrix dimensions do not match for multiplication');
    }
    let result = [];
    for (let i = 0; i < a.length; i++) {
      result[i] = [];
      for (let j = 0; j < b[0].length; j++) {
        let sum = 0;
        for (let k = 0; k < a[0].length; k++) {
          sum += a[i][k] * b[k][j];
        }
        result[i][j] = sum;
      }
    }
    return result;
  }

  // Utility: add two matrices
  static add(a, b) {
    let result = [];
    for (let i = 0; i < a.length; i++) {
      result[i] = [];
      for (let j = 0; j < a[0].length; j++) {
        result[i][j] = a[i][j] + b[i][j];
      }
    }
    return result;
  }

  // Utility: apply a function element-wise to a matrix
  static map(matrix, func) {
    let result = [];
    for (let i = 0; i < matrix.length; i++) {
      result[i] = [];
      for (let j = 0; j < matrix[0].length; j++) {
        result[i][j] = func(matrix[i][j], i, j);
      }
    }
    return result;
  }

  // Utility: transpose a matrix
  static transpose(matrix) {
    let result = [];
    for (let i = 0; i < matrix[0].length; i++) {
      result[i] = [];
      for (let j = 0; j < matrix.length; j++) {
        result[i][j] = matrix[j][i];
      }
    }
    return result;
  }

  // Activation function: sigmoid
  static sigmoid(x) {
    return 1 / (1 + Math.exp(-x));
  }

  // Derivative of sigmoid
  static dsigmoid(y) {
    // y = sigmoid(x), so derivative in terms of output y is y * (1 - y)
    return y * (1 - y);
  }

  // Feedforward
  predict(inputArray) {
    // Convert input array to matrix (column vector)
    let inputs = inputArray.map(x => [x]);

    // Hidden layer
    let hidden = SimpleNeuralNetwork.multiply(this.weightsInputHidden, inputs);
    hidden = SimpleNeuralNetwork.add(hidden, this.biasHidden);
    hidden = SimpleNeuralNetwork.map(hidden, SimpleNeuralNetwork.sigmoid);

    // Output layer
    let outputs = SimpleNeuralNetwork.multiply(this.weightsHiddenOutput, hidden);
    outputs = SimpleNeuralNetwork.add(outputs, this.biasOutput);
    outputs = SimpleNeuralNetwork.map(outputs, SimpleNeuralNetwork.sigmoid);

    // Convert output matrix to array
    return outputs.map(row => row[0]);
  }

  // Train with one example (input and target arrays)
  train(inputArray, targetArray) {
    // Convert arrays to matrices
    let inputs = inputArray.map(x => [x]);
    let targets = targetArray.map(x => [x]);

    // Feedforward
    let hidden = SimpleNeuralNetwork.multiply(this.weightsInputHidden, inputs);
    hidden = SimpleNeuralNetwork.add(hidden, this.biasHidden);
    hidden = SimpleNeuralNetwork.map(hidden, SimpleNeuralNetwork.sigmoid);

    let outputs = SimpleNeuralNetwork.multiply(this.weightsHiddenOutput, hidden);
    outputs = SimpleNeuralNetwork.add(outputs, this.biasOutput);
    outputs = SimpleNeuralNetwork.map(outputs, SimpleNeuralNetwork.sigmoid);

    // Calculate output errors (target - output)
    let outputErrors = [];
    for (let i = 0; i < targets.length; i++) {
      outputErrors[i] = [];
      for (let j = 0; j < targets[0].length; j++) {
        outputErrors[i][j] = targets[i][j] - outputs[i][j];
      }
    }

    // Calculate gradients for output layer
    let gradients = SimpleNeuralNetwork.map(outputs, SimpleNeuralNetwork.dsigmoid);
    for (let i = 0; i < gradients.length; i++) {
      for (let j = 0; j < gradients[0].length; j++) {
        gradients[i][j] *= outputErrors[i][j];
        gradients[i][j] *= this.learningRate;
      }
    }

    // Calculate deltas for weightsHiddenOutput
    let hiddenT = SimpleNeuralNetwork.transpose(hidden);
    let weightHiddenOutputDeltas = SimpleNeuralNetwork.multiply(gradients, hiddenT);

    // Adjust weights and biases for hidden-output
    for (let i = 0; i < this.weightsHiddenOutput.length; i++) {
      for (let j = 0; j < this.weightsHiddenOutput[0].length; j++) {
        this.weightsHiddenOutput[i][j] += weightHiddenOutputDeltas[i][j];
      }
    }
    for (let i = 0; i < this.biasOutput.length; i++) {
      for (let j = 0; j < this.biasOutput[0].length; j++) {
        this.biasOutput[i][j] += gradients[i][j];
      }
    }

    // Calculate hidden layer errors
    let weightsHiddenOutputT = SimpleNeuralNetwork.transpose(this.weightsHiddenOutput);
    let hiddenErrors = SimpleNeuralNetwork.multiply(weightsHiddenOutputT, outputErrors);

    // Calculate hidden gradients
    let hiddenGradient = SimpleNeuralNetwork.map(hidden, SimpleNeuralNetwork.dsigmoid);
    for (let i = 0; i < hiddenGradient.length; i++) {
      for (let j = 0; j < hiddenGradient[0].length; j++) {
        hiddenGradient[i][j] *= hiddenErrors[i][j];
        hiddenGradient[i][j] *= this.learningRate;
      }
    }

    // Calculate input-hidden deltas
    let inputsT = SimpleNeuralNetwork.transpose(inputs);
    let weightInputHiddenDeltas = SimpleNeuralNetwork.multiply(hiddenGradient, inputsT);

    // Adjust weights and biases for input-hidden
    for (let i = 0; i < this.weightsInputHidden.length; i++) {
      for (let j = 0; j < this.weightsInputHidden[0].length; j++) {
        this.weightsInputHidden[i][j] += weightInputHiddenDeltas[i][j];
      }
    }
    for (let i = 0; i < this.biasHidden.length; i++) {
      for (let j = 0; j < this.biasHidden[0].length; j++) {
        this.biasHidden[i][j] += hiddenGradient[i][j];
      }
    }
  }
}

// Example usage:

// XOR problem
const nn = new SimpleNeuralNetwork(2, 2, 1, 0.5);

const trainingData = [
  { inputs: [0, 0], targets: [0] },
  { inputs: [0, 1], targets: [1] },
  { inputs: [1, 0], targets: [1] },
  { inputs: [1, 1], targets: [0] },
];

// Train the network
for (let i = 0; i < 10000; i++) {
  let data = trainingData[Math.floor(Math.random() * trainingData.length)];
  nn.train(data.inputs, data.targets);
}

// Test the network
console.log('0 XOR 0:', nn.predict([0, 0])[0].toFixed(3));
console.log('0 XOR 1:', nn.predict([0, 1])[0].toFixed(3));
console.log('1 XOR 0:', nn.predict([1, 0])[0].toFixed(3));
console.log('1 XOR 1:', nn.predict([1, 1])[0].toFixed(3));
```

### Explanation:
- The network has an input layer, one hidden layer, and an output layer.
- Weights and biases are initialized randomly.
- The `predict` method performs a forward pass.
- The `train` method performs one step of training using backpropagation.
- The example trains the network to solve the XOR problem, a classic simple test for neural networks.

