                                .frame(width: 80)
                                .background(Color(UIColor.secondarySystemBackground))
                                .cornerRadius(8)

                            TextField("ZIP Code", text: $zipCode)
                                .textContentType(.postalCode)
                                .keyboardType(.numbersAndPunctuation)
                                .padding()
                                .frame(width: 100)
                                .background(Color(UIColor.secondarySystemBackground))
                                .cornerRadius(8)
                        }
                    }

                    // MARK: - Payment Info
                    Group {
                        Text("Payment Information")
                            .font(.title2)
                            .bold()
                            .frame(maxWidth: .infinity, alignment: .leading)

                        TextField("Card Number", text: $cardNumber)
                            .textContentType(.creditCardNumber)
                            .keyboardType(.numberPad)
                            .padding()
                            .background(Color(UIColor.secondarySystemBackground))
                            .cornerRadius(8)
                            .onChange(of: cardNumber) { newValue in
                                // Format card number with spaces every 4 digits
                                let filtered = newValue.filter { "0123456789".contains($0) }
                                let formatted = filtered.chunked(into: 4).joined(separator: " ")
                                if formatted != newValue {
                                    cardNumber = formatted
                                }
                            }

                        HStack(spacing: 15) {
                            TextField("MM/YY", text: $expirationDate)
                                .textContentType(.none) // No direct contentType for expiration date
                                .keyboardType(.numbersAndPunctuation)
                                .padding()
                                .frame(width: 100)
                                .background(Color(UIColor.secondarySystemBackground))
                                .cornerRadius(8)
                                .onChange(of: expirationDate) { newValue in
                                    // Format expiration date as MM/YY
                                    let filtered = newValue.filter { "0123456789".contains($0) }
                                    var formatted = filtered
                                    if filtered.count > 2 {
                                        let index = filtered.index(filtered.startIndex, offsetBy: 2)
                                        formatted = String(filtered[..<index]) + "/" + String(filtered[index...])
                                    }
                                    if formatted != newValue {
                                        expirationDate = String(formatted.prefix(5))
                                    }
                                }

                            SecureField("CVV", text: $cvv)
                                .textContentType(.creditCardSecurityCode)
                                .keyboardType(.numberPad)
                                .padding()
                                .frame(width: 80)
                                .background(Color(UIColor.secondarySystemBackground))
                                .cornerRadius(8)
                        }

                        TextField("Name on Card", text: $cardHolderName)
                            .textContentType(.name)
                            .autocapitalization(.words)
                            .padding()
                            .background(Color(UIColor.secondarySystemBackground))
                            .cornerRadius(8)
                    }

                    // MARK: - Submit Button
                    Button(action: {
                        if validateForm() {
                            showAlert = true
                        }
                    }) {
                        Text("Complete Purchase")
                            .foregroundColor(.white)
                            .frame(maxWidth: .infinity)
                            .padding()
                            .background(isFormValid ? Color.blue : Color.gray)
                            .cornerRadius(10)
                    }
                    .disabled(!isFormValid)
                    .padding(.top)
                }
                .padding()
            }
            .navigationTitle("Checkout")
            .alert(isPresented: $showAlert) {
                Alert(title: Text("Success"), message: Text("Your purchase has been completed."), dismissButton: .default(Text("OK")))
            }
            .onChange(of: fullName) { _ in validateForm() }
            .onChange(of: email) { _ in validateForm() }
            .onChange(of: address) { _ in validateForm() }
            .onChange(of: city) { _ in validateForm() }
            .onChange(of: state) { _ in validateForm() }
            .onChange(of: zipCode) { _ in validateForm() }
            .onChange(of: cardNumber) { _ in validateForm() }
            .onChange(of: expirationDate) { _ in validateForm() }
            .onChange(of: cvv) { _ in validateForm() }
            .onChange(of: cardHolderName) { _ in validateForm() }
        }
    }

    // MARK: - Validation
    private func validateForm() -> Bool {
        // Basic validation rules
        let isNameValid = !fullName.trimmingCharacters(in: .whitespaces).isEmpty
        let isEmailValid = email.contains("@") && email.contains(".")
        let isAddressValid = !address.trimmingCharacters(in: .whitespaces).isEmpty
        let isCityValid = !city.trimmingCharacters(in: .whitespaces).isEmpty
        let isStateValid = state.count == 2
        let isZipValid = zipCode.count >= 5 && zipCode.count <= 10

        let cardNumberDigits = cardNumber.filter { "0123456789".contains($0) }
        let isCardNumberValid = cardNumberDigits.count == 16

        let isExpirationValid = {
            let parts = expirationDate.split(separator: "/")
            if parts.count == 2,
               let month = Int(parts[0]),
               let year = Int(parts[1]),
               (1...12).contains(month),
               year >= 23 && year <= 99 { // crude year check (assumes 2023+)
                return true
            }
            return false
        }()

        let isCVVValid = cvv.count == 3 || cvv.count == 4

        let isCardHolderValid = !cardHolderName.trimmingCharacters(in: .whitespaces).isEmpty

        let valid = isNameValid && isEmailValid && isAddressValid && isCityValid && isStateValid && isZipValid && isCardNumberValid && isExpirationValid && isCVVValid && isCardHolderValid

        DispatchQueue.main.async {
            self.isFormValid = valid
        }

        return valid
    }
}

// MARK: - Helper Extension for Formatting
fileprivate extension String {
    func chunked(into size: Int) -> [String] {
        var startIndex = self.startIndex
        var results = [String]()

        while startIndex < self.endIndex {
            let endIndex = self.index(startIndex, offsetBy: size, limitedBy: self.endIndex) ?? self.endIndex
            results.append(String(self[startIndex..<endIndex]))
            startIndex = endIndex
        }

        return results
    }
}

